import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const $=s=>document.querySelector(s), world=document.querySelector('#world');
const scene=new THREE.Scene(); scene.background=new THREE.Color(0x9ca99e); scene.fog=new THREE.Fog(0x9ca99e,34,94);
const camera=new THREE.PerspectiveCamera(43,innerWidth/innerHeight,.1,180);
const renderer=new THREE.WebGLRenderer({antialias:true, powerPreference:'high-performance'}); renderer.setPixelRatio(Math.min(devicePixelRatio,1.8)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.18; world.appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight(0xdde8dc,0x3e4635,2.1)); const sun=new THREE.DirectionalLight(0xffe2b4,2.6); sun.position.set(-15,26,10); sun.castShadow=true; sun.shadow.mapSize.set(2048,2048); sun.shadow.camera.left=-42;sun.shadow.camera.right=42;sun.shadow.camera.top=42;sun.shadow.camera.bottom=-42;sun.shadow.bias=-.0003;scene.add(sun);
const mat=(color,rough=.88,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const mats={grass:mat(0x58694d),grass2:mat(0x647354),road:mat(0x454947),sidewalk:mat(0x85877d),line:mat(0xc3b99a),concrete:mat(0x777a70),brick:mat(0x876b58),cream:mat(0xb4a58a),roof:mat(0x4c4941),roof2:mat(0x645249),glass:mat(0x49676b,.45),dark:mat(0x282e2b),wood:mat(0x664c37),leaf:mat(0x455b3f),leaf2:mat(0x596a43),trunk:mat(0x594837),rust:mat(0x8c4c36),carblue:mat(0x4c6161),carcream:mat(0xaaa18a),red:mat(0x93483b),yellow:mat(0xc6a454),skin:mat(0xa58b70),zskin:mat(0x9a8f74),cloth:mat(0x4b5148),pants:mat(0x343b37)};
const geo={box:new THREE.BoxGeometry(1,1,1),sphere:new THREE.SphereGeometry(1,10,8),cyl:new THREE.CylinderGeometry(.5,.5,1,8),cone:new THREE.ConeGeometry(1,1,8)};
function box(parent,x,y,z,w,h,d,material,cast=true){const o=new THREE.Mesh(geo.box,material);o.position.set(x,y,z);o.scale.set(w,h,d);o.castShadow=cast;o.receiveShadow=true;parent.add(o);return o}
function cylinder(parent,x,y,z,r,h,material,segments=8){const o=new THREE.Mesh(new THREE.CylinderGeometry(r*.78,r,h,segments),material);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}
function group(parent,x=0,y=0,z=0){const g=new THREE.Group();g.position.set(x,y,z);parent.add(g);return g}
function rand(a,b){return a+Math.random()*(b-a)}
// Quiet neighborhood grid: lawn, main road, curb, and a stretch of tired little homes.
const ground=new THREE.Mesh(new THREE.PlaneGeometry(150,150),mats.grass);ground.rotation.x=-Math.PI/2;ground.position.y=-.12;ground.receiveShadow=true;scene.add(ground);
box(scene,0,-.045,0,110,.12,11,mats.road,false);
for(let x=-52;x<54;x+=5.5) box(scene,x,.02,0,2.6,.015,.11,mats.line,false);
for(const side of [-1,1]){box(scene,0,.03,side*6.05,110,.12,1.1,mats.sidewalk,false);box(scene,0,.01,side*6.72,110,.10,.18,mats.concrete,false)}
// subtle cracked lane patches
for(let i=0;i<34;i++){const x=rand(-50,50),z=rand(-4.7,4.7);box(scene,x,.018,z,rand(.25,1.1),.012,.025,mat(0x555957),false)}
function makeTree(x,z,scale=1){const g=group(scene,x,0,z);cylinder(g,0,.8*scale,0,.17*scale,1.6*scale,mats.trunk,7);for(let i=0;i<3;i++){const m=new THREE.Mesh(geo.sphere,i%2?mats.leaf:mats.leaf2);m.position.set(rand(-.17,.17)*scale,(1.8+i*.38)*scale,rand(-.16,.16)*scale);m.scale.set((.75+rand(0,.3))*scale,(.65+rand(0,.25))*scale,(.7+rand(0,.3))*scale);m.castShadow=true;m.receiveShadow=true;g.add(m)}return g}
function makeHouse(x,z,variant=0){const g=group(scene,x,0,z), w=variant===1?10:8.5,d=variant===1?7:7.8,wall=variant===1?mats.cream:mats.brick,roof=variant%2?mats.roof2:mats.roof;
box(g,0,1.35,0,w,2.7,d,wall);box(g,0,2.82,0,w+.55,.22,d+.5,mat(0xddd0b6));
// roof as two sloped planes
const roofA=new THREE.Mesh(new THREE.BoxGeometry(w+.7,.35,d/2+.5),roof);roofA.position.set(0,3.55,-d*.25);roofA.rotation.x=-.48;roofA.castShadow=true;g.add(roofA);const roofB=roofA.clone();roofB.position.z=d*.25;roofB.rotation.x=.48;g.add(roofB);
// front wall faces the street at center z=+d/2
box(g,-.05,1.02,d/2+.035,.95,2.02,.08,mats.wood);box(g,-.05,1.03,d/2+.09,.66,1.6,.035,mat(0x343c38));
for(const wx of [-w*.31,w*.31]){box(g,wx,1.72,d/2+.06,1.12,.92,.09,mats.glass);box(g,wx,1.72,d/2+.115,1.14,.10,.025,mats.cream);box(g,wx,1.72,d/2+.115,.10,.96,.025,mats.cream);box(g,wx,1.2,d/2+.15,1.35,.17,.22,roof)}
// side windows
for(const sz of [-d*.26,d*.26])box(g,w/2+.04,1.72,sz,.08,.82,1.05,mats.glass);
// front porch + steps
box(g,0,.38,d/2+.85,w*.55,.18,1.1,mats.concrete);box(g,0,.2,d/2+1.35,w*.65,.16,.48,mats.sidewalk);
for(const px of [-w*.38,w*.38])cylinder(g,px,1.15,d/2+1.02,.10,1.65,mats.cream,8);
// chimney
box(g,-w*.31,3.25,-d*.25,.65,1.15,.62,mats.brick);
// foundation and trim
box(g,0,.18,0,w+.2,.28,d+.18,mats.concrete);
return g}
// houses set back from the road, lots of trees and backyard clutter
for(const side of [-1,1]){
  const z=side*17;
  for(let i=0;i<7;i++){
    const x=-43+i*14+rand(-1.5,1.5), g=makeHouse(x,z+(i%2?1:-1),i%3===0?1:0);
    // front walk from porch toward curb
    box(scene,x,.045,side*11,1.1,.07,5,mats.concrete,false);
    for(let t=0;t<3;t++)makeTree(x+rand(-6,6),side*rand(9,27),rand(.75,1.22));
    // mailbox / bins / fence fragments
    cylinder(scene,x+5,.65,side*10.4,.07,1.25,mats.dark,6);box(scene,x+5,.98,side*10.4,.5,.28,.32,mats.wood);
    if(i%2===0){for(let f=-1;f<=1;f++)box(scene,x+f*.9,.42,side*12.7,.11,.84,.12,mats.cream,false);box(scene,x,.48,side*12.7,3.1,.12,.12,mats.cream,false)}
  }
}

