let started=false,dead=false,modalOpen=false,health=100,stamina=100,hunger=12,thirst=8,food=1,med=0,ammo=0,dayMinutes=494,moveX=0,moveZ=0,lastTime=0,attackCooldown=0,invuln=0,toastTimer=0,activeLoot=null;
const keys={};
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');toastTimer=2.2}
function clamp(v,a,b){return Math.max(a,Math.min(b,v))}
function distance(a,b){return Math.hypot(a.x-b.x,a.z-b.z)}
function nearestLoot(){let best=null,dist=2.8;for(const l of lootables){if(l.searched)continue;const d=distance(player.position,l.g.position);if(d<dist){dist=d;best=l}}return best}
function nearestZombie(max=2.3){let best=null,dist=max;for(const z of zombies){if(!z.alive)continue;const d=distance(player.position,z.g.position);if(d<dist){dist=d;best=z}}return best}
function shove(){if(!started||dead||modalOpen||attackCooldown>0)return;attackCooldown=.58;stamina=Math.max(0,stamina-8);const z=nearestZombie(2.6);if(z){z.hp--;const dx=z.g.position.x-player.position.x,dz=z.g.position.z-player.position.z,dd=Math.hypot(dx,dz)||1;z.g.position.x+=dx/dd*2.7;z.g.position.z+=dz/dd*2.7;z.g.rotation.y=Math.atan2(dx,dz);z.stun=.85;if(z.hp<=0){z.alive=false;z.g.rotation.x=-Math.PI/2;z.g.position.y=.12;toast('The infected one falls. Keep moving.');}else toast('A hard shove buys you a moment.')}else toast('You shove at empty air.');}
function search(){if(!started||dead||modalOpen)return;const l=nearestLoot();if(!l){toast('Nothing close enough to search.');return}activeLoot=l;modalOpen=true;$('#lootTitle').textContent=l.name;$('#lootDesc').textContent=l.searched?'Nothing left here.':`You search the ${l.name.toLowerCase()}. Take what you can carry.`;const rows=$('#lootRows');rows.innerHTML='';if(l.searched){rows.innerHTML='<div class="loot-row"><span>Picked clean</span><span>—</span></div>'}else for(const [name,type,count] of l.items){const row=document.createElement('div');row.className='loot-row';row.innerHTML=`<span>${name} <span style="color:#92988b">×${count}</span></span>`;const btn=document.createElement('button');btn.textContent='TAKE';btn.onclick=()=>{if(type==='food')food+=count;if(type==='med')med+=count;if(type==='ammo')ammo+=count;if(type==='thirst')thirst=Math.max(0,thirst-24*count);if(type==='weapon')toast('A kitchen knife. Better than bare hands.');l.searched=true;l.glow.visible=false;row.innerHTML=`<span>${name}</span><span style="color:#e6ad58">TAKEN</span>`;refreshInventory();if([...rows.querySelectorAll('button')].every(b=>b.textContent==='TAKEN'))$('#lootDesc').textContent='You pocket the useful things. The rest can wait.'};row.appendChild(btn);rows.appendChild(row)}$('#lootModal').classList.add('show');$('#crosshair').style.display='none'}
function closeLoot(){modalOpen=false;activeLoot=null;$('#lootModal').classList.remove('show');$('#crosshair').style.display='block'}
function refreshInventory(){$('#foodQty').textContent=food;$('#medQty').textContent=med;$('#ammoQty').textContent=ammo}
function updateHud(){for(const [id,v] of [['health',health],['stamina',stamina],['hunger',hunger],['thirst',thirst]]){$(`#${id}Bar`).style.width=`${v}%`;$(`#${id}Num`).textContent=`${Math.round(v)}%`}
$('#condition').textContent=health<30?'Critical':hunger>75?'Starving':thirst>75?'Dehydrated':'Clear';$('#status').textContent=stamina<20?'EXHAUSTED':moveX||moveZ?'ON THE MOVE':'UNHURRIED';
let near=0;for(const z of zombies)if(z.alive&&distance(player.position,z.g.position)<13)near++;$('#nearCount').textContent=`${near} HOSTILE${near===1?'':'S'}`;$('#nearText').innerHTML=near?`${near} infected ${near===1?'is':'are'} within earshot.<br><span style="color:#d46b59">Don't let them surround you.</span>`:'The street is quiet.<br>For now.';
const mins=Math.floor(dayMinutes)%60,hour=Math.floor(dayMinutes/60)%12||12,ampm=dayMinutes<720?'AM':'PM';$('#clock').textContent=`${String(hour).padStart(2,'0')}:${String(mins).padStart(2,'0')} ${ampm}`}
function begin(){started=true;$('#intro').classList.add('hidden');toast('Riverside, Knox County. Monday morning.');renderer.domElement.requestPointerLock?.()}
$('#start').addEventListener('click',begin);$('#lootClose').addEventListener('click',closeLoot);$('#lootModal').addEventListener('click',e=>{if(e.target.id==='lootModal')closeLoot()});
window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Space')shove();if(e.code==='KeyF')search();if(e.code==='Escape'&&modalOpen)closeLoot();if(e.code==='Digit1'&&food>0){food--;hunger=Math.max(0,hunger-25);toast('You eat a can of beans.');refreshInventory()}if(e.code==='Digit2'&&med>0){med--;health=Math.min(100,health+35);toast('You patch yourself up.');refreshInventory()}});window.addEventListener('keyup',e=>keys[e.code]=false);renderer.domElement.addEventListener('pointerdown',e=>{if(started&&e.button===0)shove()});
$('#attackTouch').addEventListener('pointerdown',e=>{e.preventDefault();shove()});$('#searchTouch').addEventListener('pointerdown',e=>{e.preventDefault();search()});
// Drag joystick works on phones; WASD remains the main keyboard scheme.
let stickPointer=null;const stick=$('#stick');stick.addEventListener('pointerdown',e=>{stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);joy(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickPointer)joy(e)});stick.addEventListener('pointerup',e=>{if(e.pointerId===stickPointer){moveX=0;moveZ=0;stickPointer=null;stick.style.setProperty('--jx','0px');stick.style.setProperty('--jy','0px')}});function joy(e){const r=stick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),len=Math.hypot(dx,dy),scale=Math.min(1,len/42);moveX=dx/(len||1)*scale;moveZ=dy/(len||1)*scale;stick.style.setProperty('--jx',`${moveX*33}px`);stick.style.setProperty('--jy',`${moveZ*33}px`)}

